class GrowingArray:
    def __init__(self, data: np.ndarray, buffer_size=1000):
        self._size = len(data)
        self._buffer = data
        self._buffer_grow_size = buffer_size
        self.dtype = self._buffer.dtype
    @property
    def shape(self):
        return (self._size,) + self._buffer.shape[1:]
    def __len__(self):
        return self._size
    def __array__(self):
        return self._buffer[: self._size]
    def add(self, new_data):
        shortage = self._size + len(new_data) - len(self._buffer)
        if shortage > 0:
            zeros = np.zeros((self._buffer_grow_size + shortage,) + self._buffer.shape[1:], dtype=self._buffer.dtype)
            self._buffer = np.concatenate((self._buffer, zeros), 0)
        self._buffer[self._size : self._size + len(new_data)] = new_data
        self._size += len(new_data)


class Trajectory:
    keys = ["states", "actions", "rewards", "pixels"]
    def __init__(self, states: np.ndarray, actions: np.ndarray, rewards: np.ndarray, pixels: np.ndarray, info=None):
        n = len(states)
        self.states = GrowingArray(states)
        self.actions = GrowingArray(actions.reshape((n, -1)))
        self.rewards = GrowingArray(np.nan_to_num(rewards))
        self.pixels = GrowingArray(pixels)
        self.info = info or {}
    @property
    def arrays(self):
        return [self.states, self.actions, self.rewards, self.pixels]
    @classmethod
    def add_step(cls, old, *arrays, info=None):
        arrays = [np.asarray(x) for x in arrays]
        arrays[1] = np.atleast_1d(arrays[1])
        if old is None:
            return cls(*[x[None] for x in arrays], info={k: [v] for k, v in (info or {}).items()})
        for old_arr, new_arr in zip(old.arrays, arrays):
            old_arr.add(np.asarray(new_arr)[None])
        newinfo = ({k: np.concatenate([old.info[k], [info[k]]]) for k in old.info.keys()} if info and old.info else None)
        old.info = newinfo
        return old
    def finished(self):
        self.states = np.asarray(self.states)
        self.actions = np.asarray(self.actions)
        self.rewards = np.asarray(self.rewards)
        self.pixels = np.asarray(self.pixels)
    def reward_sum(self):
        return np.sum(self.rewards)
    @staticmethod
    def reward_sum_mean(trajectories):
        return np.mean([t.reward_sum() for t in trajectories]).item()


# From ccil/utils/policy_runner.py
class PolicyRunner:
    def __init__(self, env, agent, state_encoder):
        self.env = env
        self.agent = agent
        self.state_encoder = state_encoder

    def run_episode(self):
        state, done = self.env.reset(), False
        trajectory = None
        while not done:
            x = self.state_encoder.step(state, trajectory)
            action = self.agent(x).item()

            prev_action, prev_state = action, state
            state, rew, done, info = self.env.step(action)

            trajectory = Trajectory.add_step(
                trajectory, prev_state, prev_action, rew, None, info=info
            )
        trajectory.finished()
        return trajectory

    def run_num_episodes(self, num_episodes, verbose=False):
        trajectories = []
        for _ in range(num_episodes):
            trajectory = self.run_episode()
            trajectories.append(trajectory)
        return trajectories


def run_fixed_mask(env, policy_model, state_encoder, mask, num_episodes):
    agent = FixedMaskPolicyAgent(policy_model, mask)
    runner = PolicyRunner(env, agent, state_encoder)
    trajectories = runner.run_num_episodes(num_episodes)
