def get_ortho_diff(n_env):
    ones = torch.ones(n_env,1) 
    a,_ = torch.linalg.qr(ones, mode='complete')
    # U_mean = a[0:1]  # ones.T /math.sqrt(n_env)
    U_diff = a[1:]
    return U_diff

