def get_mlp(n_in: int, n_out: int,
            layers: List[int],
            layer_normalization: Union[None, Literal["bn"], Literal["gn"]] = None,
            output_normalization: Union[None, Literal["bn"], Literal["gn"]] = None,
            output_normalization_kwargs=None, act_inf_param=0.02, linear=False):
    modules: List[nn.Module] = []
    def add_module(n_layer_in: int, n_layer_out: int, last_layer: bool = False, mid_layer: bool = False):
        modules.append(nn.Linear(n_layer_in, n_layer_out))
        if not last_layer:
            if layer_normalization == "bn":
                modules.append(nn.BatchNorm1d(n_layer_out))
            elif layer_normalization == "gn":
                modules.append(nn.GroupNorm(1, n_layer_out))
            if not linear:
               modules.append(nn.LeakyReLU(negative_slope=act_inf_param))
        else:
            if output_normalization == "bn":
                modules.append(nn.BatchNorm1d(n_layer_out))
            elif output_normalization == "gn":
                modules.append(nn.GroupNorm(1, n_layer_out))
        return n_layer_out
    if len(layers) > 0:
        n_out_last_layer = n_in
    else:
        assert n_in == n_out, "Network with no layers must have matching n_in and n_out"
        modules.append(nn.Identity()) # Replaced Lambda with Identity for general compatibility
    layers.append(n_out)
    for i, l in enumerate(layers):
        n_out_last_layer = add_module(n_out_last_layer, l, i == len(layers)-1)
    if output_normalization_kwargs is None:
        output_normalization_kwargs = {}
    return nn.Sequential(*modules)

def construct_invertible_mlp(n: int = 20, n_layers: int = 2, n_iter_cond_thresh: int = 10000,
                             cond_thresh_ratio: float = 0.25,
                             weight_matrix_init: Union[Literal["pcl"], Literal["rvs"]] = 'pcl',
                             act_fct: Union[Literal["relu"], Literal["leaky_relu"], Literal["elu"],
                                            Literal["smooth_leaky_relu"], Literal["softplus"]] = 'leaky_relu'
                             ):
    class SmoothLeakyReLU(nn.Module):
        def __init__(self, alpha=0.2):
            super().__init__()
            self.alpha = alpha
        def forward(self, x):
            return self.alpha * x + (1 - self.alpha) * torch.log(1 + torch.exp(x))
    def get_act_fct(act_fct):
        if act_fct == 'relu': return torch.nn.ReLU, {}, 1
        if act_fct == 'leaky_relu': return torch.nn.LeakyReLU, {'negative_slope': 0.2}, 1
        elif act_fct == 'elu': return torch.nn.ELU, {'alpha': 1.0}, 1
        elif act_fct == 'max_out': raise NotImplemented()
        elif act_fct == 'smooth_leaky_relu': return SmoothLeakyReLU, {'alpha': 0.2}, 1
        elif act_fct == 'softplus': return torch.nn.Softplus, {'beta': 1}, 1
        else: raise Exception(f'activation function {act_fct} not defined.')
    layers = []
    act_fct, act_kwargs, act_fac = get_act_fct(act_fct)
    def l2_normalize(Amat, axis=0):
        l2norm = np.sqrt(np.sum(Amat * Amat, axis))
        Amat = Amat / l2norm
        return Amat
    condList = np.zeros([n_iter_cond_thresh])
    if weight_matrix_init == 'pcl':
        for i in range(n_iter_cond_thresh):
            A = np.random.uniform(-1, 1, [n, n])
            A = l2_normalize(A, axis=0)
            condList[i] = np.linalg.cond(A)
        condList.sort()
    condThresh = condList[int(n_iter_cond_thresh * cond_thresh_ratio)]
    for i in range(n_layers):
        lin_layer = nn.Linear(n, n, bias=False)
        if weight_matrix_init == 'pcl':
            condA = condThresh + 1
            while condA > condThresh:
                weight_matrix = np.random.uniform(-1, 1, (n, n))
                weight_matrix = l2_normalize(weight_matrix, axis=0)
                condA = np.linalg.cond(weight_matrix)
            lin_layer.weight.data = torch.tensor(weight_matrix, dtype=torch.float32)
        elif weight_matrix_init == 'rvs':
            weight_matrix = ortho_group.rvs(n)
            lin_layer.weight.data = torch.tensor(weight_matrix, dtype=torch.float32)
        elif weight_matrix_init == 'expand': pass
        else: raise Exception(f'weight matrix {weight_matrix_init} not implemented')
        layers.append(lin_layer)
        if i < n_layers - 1:
            layers.append(act_fct(**act_kwargs))
    mixing_net = nn.Sequential(*layers)
    for p in mixing_net.parameters():
        p.requires_grad = False
    return mixing_net

