    rng_data_gen=np.random.default_rng(seed)
    if manifold == "nn":
        h_dim = x_dim
        neg_slope = 0.2
        device = "cuda:0" if torch.cuda.is_available() else "cpu"
        if load_f is not None:
            dd = np.load(load_f)
            W0 = [dd[f_key] for f_key in dd]
        else:
            W0 = []
            for l_idx in range(n_layers):
                Wi = rng_data_gen.normal(size=(h_dim, x_dim))
                Wi = np.linalg.qr(Wi.T)[0].T
                Wi *= np.sqrt(2 / (1 + neg_slope ** 2)) * np.sqrt(2. / (x_dim + h_dim))
                W0.append(Wi)
            save_path = os.path.join(save_dir, 'f.npz')
            np.savez(save_path,*W0)
        W=[]
        for l_idx in range(n_layers):
            Wi = W0[l_idx]
            Wi = torch.Tensor(Wi).to(device)
            Wi.requires_grad = False
            W.append(Wi)
        def decoder(z):
            with torch.no_grad():
                z = torch.Tensor(z).to(device)
                h = torch.matmul(z, W[0])
                if n_layers>1:
                    for l_idx in range(n_layers-1):
                        if smooth:
                            h = neg_slope * h + (1 - neg_slope) * torch.log(1 + torch.exp(h))
                        else:
                            h = torch.maximum(neg_slope * h, h)
                        h = torch.matmul(h, W[l_idx+1])
            return h
    else: raise NotImplementedError(f"The manifold {manifold} is not implemented.")
    return decoder

class Constrained_DE(cooper.ConstrainedMinimizationProblem):
    def __init__(self, latent_dim, n_classes):
        self.criterion = nn.MSELoss(reduction='sum')
        super().__init__(is_constrained=True)

    def compute_loss(self, x, x_hat, mu, args, masks, device):
        mini_batch = args.batch_size // len(masks)
        log_p_x_given_z = self.criterion(x_hat, x)
        stat_loss = 0
        if args.oracle=='oracle':
            log_var_prior = torch.tensor(masks).to(device)
            log_var_prior[log_var_prior==0]=-10
        mu_prior = torch.ones(args.nn).to(device)*2
        for k in range(len(masks)):
            if k==len(masks)-1:
                mu_k = mu[k*mini_batch:,:]
            else:
                mu_k=mu[k*mini_batch:(k+1)*mini_batch,:]
            diffs = mu_k - mu_prior
            if args.oracle=='oracle':
                std = (log_var_prior[k,:]/2).exp()
            else:
                var = torch.mean(torch.pow(diffs, 2.0))
                std = torch.pow(var, 0.5)
            zscores = diffs / (std+1e-9)
            skews = torch.mean(torch.pow(zscores, 3.0),dim=0)
            kurtoses = torch.mean(torch.pow(zscores, 4.0),dim=0) - 3.0
            stat_loss += torch.mean(torch.abs(skews))+torch.mean(torch.abs(kurtoses))
        return log_p_x_given_z,stat_loss

    def closure(self,  inputs, f_fn, g_model, f_hat_model, scale_val, args, masks, device):
        x = f_fn(inputs)
        x = x*scale_val
        z_mu = g_model(x)
        z_hat = z_mu
        x_hat = f_hat_model(z_hat)
        loss,stat_loss = self.compute_loss(x, x_hat, z_mu, args, masks, device)
        ineq_defect = torch.sum(torch.abs(z_hat))/args.batch_size/args.z_n - args.sparse_level
        return cooper.CMPState(loss=loss+stat_loss, ineq_defect=ineq_defect, eq_defect=None)

